(() => {
 const sections=["registration","clan","extra","emotions","menu"],footerActions={registration:["✎ Изменить","‹ Назад"],clan:["Перейти","‹ Назад"],extra:["Открыть","‹ Назад"],emotions:["Сохранить","‹ Назад"],menu:["Выбрать","‹ Назад"]};
 let current=0,authMode="register",lastSelectedAction=null;const $=id=>document.getElementById(id);
 const toast=message=>{const el=$("toast");el.textContent=message;el.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove("show"),2600);};
 function showSection(i){current=(i+sections.length)%sections.length;sections.forEach((n,j)=>$("section-"+n).classList.toggle("active",j===current));document.querySelectorAll("[data-section]").forEach(b=>b.classList.toggle("active",b.dataset.section===sections[current]));$("footer-left").textContent=footerActions[sections[current]][0];$("footer-right").textContent=footerActions[sections[current]][1];}
 function setMode(mode){authMode=mode;document.querySelectorAll("[data-auth]").forEach(b=>b.classList.toggle("active",b.dataset.auth===mode));$("submit-auth").textContent=mode==="login"?"Войти":"Создать ник";$("recovery-login-label").classList.toggle("hidden",mode!=="login");$("recovery-login").required=mode==="login";$("form-error").textContent="";}
 function showAccount(account,code){$("auth-form").classList.add("hidden");$("account-state").classList.remove("hidden");$("account-name").textContent=account.nickname;$("avatar").textContent="🧑";if(code){$("recovery-value").textContent=code;$("recovery-value").classList.add("recovery-code");}loadPlayerProfile();toast("Добро пожаловать в NEXORA");}
 async function loadPlayerProfile(){try{const r=await fetch("/api/account/profile");if(!r.ok)return;const d=await r.json();if(d.character){$("head-choice").value=String(d.character.head_id);$("body-choice").value=String(d.character.body_id);$("create-character").textContent="Обновить персонажа";}else $("create-character").textContent="Персонаж";}catch{}}
 $("auth-form").addEventListener("submit",async e=>{e.preventDefault();$("form-error").textContent="";const payload=authMode==="login"?{nickname:$("nickname").value,recoveryCode:$("recovery-login").value}:{nickname:$("nickname").value};const endpoint=authMode==="login"?"/api/auth/login":"/api/auth/register";$("submit-auth").disabled=true;try{const r=await fetch(endpoint,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)}),d=await r.json();if(!r.ok)throw Error(d.error||"Ошибка запроса");showAccount(d.account,d.recoveryCode||null);}catch(err){$("form-error").textContent=err.message;}finally{$("submit-auth").disabled=false;$("submit-auth").textContent=authMode==="login"?"Войти":"Создать ник";}});
 $("recovery-generate").addEventListener("click",async()=>{try{const r=await fetch("/api/account/recovery-code",{method:"POST"}),d=await r.json();if(!r.ok)throw Error(d.error||"Не удалось создать код");$("recovery-value").textContent=d.recoveryCode;$("recovery-value").classList.add("recovery-code");toast("Новый код создан. Старый больше не действует.");}catch(e){toast(e.message);}});
 $("create-character").addEventListener("click",async()=>{const b=$("create-character");b.disabled=true;$("character-error").textContent="";try{const r=await fetch("/api/character",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({headId:Number($("head-choice").value),bodyId:Number($("body-choice").value)})}),d=await r.json();if(!r.ok)throw Error(d.error||"Не удалось создать персонажа");b.textContent="Обновить персонажа";toast("Персонаж сохранён");}catch(e){$("character-error").textContent=e.message;}finally{b.disabled=false;}});
 document.querySelectorAll("[data-auth]").forEach(b=>b.addEventListener("click",()=>setMode(b.dataset.auth)));
 document.querySelectorAll("[data-section]").forEach(b=>b.addEventListener("click",()=>showSection(sections.indexOf(b.dataset.section))));
 document.querySelectorAll(".emotion").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll(".emotion").forEach(x=>x.classList.remove("active"));b.classList.add("active");lastSelectedAction=b.querySelector("span").textContent;toast("Статус выбран: "+lastSelectedAction);}));
 document.querySelectorAll("[data-action]").forEach(b=>b.addEventListener("click",()=>{const a=b.dataset.action;lastSelectedAction=a;if(a==="emotions")showSection(3);else if(a==="my-info"||a==="settings")fetch("/api/account/profile").then(r=>r.json()).then(d=>toast(d.account?"Профиль: "+d.account.nickname:(d.error||"Войдите в аккаунт."))).catch(()=>toast("Нет связи с сервером"));else if(a==="help")toast("Раздел помощи NEXORA");else toast("Раздел «"+b.textContent.trim()+"» подготовлен к подключению.");}));
 $("footer-right").addEventListener("click",()=>showSection(current-1));$("footer-left").addEventListener("click",()=>{if(current===0){$("nickname").focus();toast("Профиль игрока");}else if(current===3){const a=document.querySelector(".emotion.active span");toast(a?"Статус сохранён для текущего сеанса":"Выберите эмоцию");}else toast("Выберите пункт меню");});
 $("logout").addEventListener("click",async()=>{await fetch("/api/auth/logout",{method:"POST"});$("account-state").classList.add("hidden");$("auth-form").classList.remove("hidden");$("nickname").value="";$("recovery-login").value="";$("recovery-value").textContent="Код доступен только владельцу аккаунта.";$("recovery-value").classList.remove("recovery-code");setMode("login");toast("Вы вышли из аккаунта");});
 async function checkSession(){try{const r=await fetch("/api/auth/me"),d=await r.json();if(d.authenticated)showAccount(d.account,null);}catch{}}
 async function updateStatus(){try{const [s,t]=await Promise.all([fetch("/api/status"),fetch("/api/account/online")]),status=await s.json(),online=await t.json();$("connection").textContent=status.database==="connected"?"● Сервер онлайн · "+online.online+" сессий":"● Сервер доступен, БД недоступна";}catch{$("connection").textContent="● Нет связи";}}
 function updateTime(){$("header-time").textContent=new Intl.DateTimeFormat("ru-RU",{hour:"2-digit",minute:"2-digit"}).format(new Date());}
 showSection(0);setMode("register");checkSession();updateStatus();updateTime();setInterval(updateTime,1000);setInterval(updateStatus,30000);
})();